<boltAction type="file" filePath="src/app.css">.gm-page {
  padding-block: 48px 128px;
  position: relative;
}

.gm-notice {
  margin-bottom: 24px;
}

.gm-view {
  animation: gm-fade 240ms ease-out;
}

/* 섹션 사이 리듬을 전체적으로 넓힘 */
.gm-view > .cr-stack-24 {
  display: flex;
  flex-direction: column;
  gap: 40px;
}

/* ---------- header ---------- */
.gm-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-bottom: 8px;
}

.gm-header-title {
  flex: 1;
  min-width: 0;
}

.gm-header > .cr-stack-4:first-child {
  flex: 1;
  min-width: 0;
  gap: 8px;
}

.gm-icon-btn {
  padding: 10px;
  min-width: 48px;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ---------- stat cards ---------- */
.gm-stat {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 28px 24px;
  transition: transform 180ms ease-out, border-color 180ms ease-out;
}

.gm-stat:hover {
  transform: translateY(-2px);
  border-color: var(--accent);
}

.gm-stat-value {
  font-size: 32px;
  font-weight: 600;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.gm-stat-value[data-tone='accent'] {
  color: var(--accent);
}

.gm-stat-value[data-tone='warn'] {
  color: var(--warn);
}

.gm-stat-value[data-tone='muted'] {
  color: var(--text);
}

.gm-stat-unit {
  font-size: 15px;
  font-weight: 500;
  color: var(--muted);
}

/* ---------- search + chips ---------- */
.gm-searchbar {
  position: relative;
  display: flex;
  align-items: center;
}

.gm-search-icon {
  position: absolute;
  left: 16px;
  color: var(--muted);
  pointer-events: none;
}

.gm-search-input {
  padding-left: 44px;
  padding-block: 14px;
  width: 100%;
}

.gm-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.gm-chip {
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  border-radius: 999px;
  padding: 10px 18px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  min-height: 40px;
  transition: background 160ms ease-out, color 160ms ease-out, border-color 160ms ease-out;
}

.gm-chip:hover {
  border-color: var(--accent);
  color: var(--text);
}

.gm-chip.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-contrast, #fff);
}

/* ---------- member list ---------- */
.gm-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.gm-row {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  text-align: left;
  padding: 20px 22px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card, transparent);
  cursor: pointer;
  font-family: inherit;
  min-height: 84px;
  transition: transform 160ms ease-out, border-color 160ms ease-out, background 160ms ease-out;
}

.gm-row:hover {
  transform: translateY(-1px);
  border-color: var(--accent);
}

.gm-avatar {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--accent);
  color: var(--accent-contrast, #fff);
  font-size: 15px;
  font-weight: 600;
}

.gm-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.gm-row-top {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.gm-chev {
  flex: none;
  color: var(--muted);
}

.gm-strong {
  font-weight: 600;
}

.gm-muted {
  color: var(--muted);
}

.gm-between {
  justify-content: space-between;
  width: 100%;
}

.gm-warn-text {
  color: var(--warn);
}

.gm-err-text {
  color: var(--err);
}

/* ---------- detail ---------- */
.gm-panel {
  padding: 28px 24px;
}

.gm-remain {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.gm-remain-value {
  font-size: 44px;
  font-weight: 600;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.gm-remain-value[data-tone='ok'] {
  color: var(--accent);
}

.gm-remain-value[data-tone='warn'] {
  color: var(--warn);
}

.gm-remain-value[data-tone='err'] {
  color: var(--err);
}

.gm-bar {
  height: 6px;
  border-radius: 999px;
  background: var(--border);
  overflow: hidden;
}

.gm-bar-fill {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: 999px;
  transition: width 400ms ease-out;
}

.gm-info-line {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding-block: 2px;
}

.gm-info-icon {
  display: inline-flex;
  color: var(--muted);
}

.gm-info-label {
  min-width: 64px;
}

.gm-divider {
  height: 1px;
  background: var(--border);
  margin-block: 4px;
}

/* ---------- timeline ---------- */
.gm-timeline {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.gm-timeline-item {
  display: flex;
  gap: 16px;
  padding: 18px 0;
  border-bottom: 1px solid var(--border);
}

.gm-timeline-item:last-child {
  border-bottom: none;
}

.gm-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  margin-top: 8px;
}

.gm-dot[data-type='charge'] {
  background: var(--ok);
}

.gm-dot[data-type='use'] {
  background: var(--accent);
}

.gm-timeline-main {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.gm-danger-zone {
  padding-top: 28px;
  border-top: 1px solid var(--border);
}

/* ---------- form ---------- */
.gm-form {
  padding: 32px 28px;
}

/* ---------- empty ---------- */
.gm-empty {
  padding: 48px 32px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* ---------- fab ---------- */
.gm-fab {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 20;
  box-shadow: 0 6px 20px rgb(0 0 0 / 0.18);
}

@media (min-width: 1024px) {
  .gm-fab {
    right: calc(50vw - 536px);
  }
}

/* ---------- modal ---------- */
.gm-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 0.4);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  z-index: 40;
  padding: 16px;
  animation: gm-fade 180ms ease-out;
}

.gm-modal {
  width: 100%;
  max-width: 440px;
  padding: 32px 28px;
  animation: gm-rise 220ms ease-out;
}

@media (min-width: 640px) {
  .gm-modal-backdrop {
    align-items: center;
  }
}

/* ---------- toast ---------- */
.gm-toast {
  position: fixed;
  left: 50%;
  bottom: 96px;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg);
  box-shadow: 0 6px 20px rgb(0 0 0 / 0.18);
  animation: gm-rise 200ms ease-out;
  max-width: calc(100% - 32px);
}

.gm-toast-icon {
  display: inline-flex;
}

.gm-toast-icon[data-tone='ok'] {
  color: var(--ok);
}

.gm-toast-icon[data-tone='err'] {
  color: var(--err);
}

/* ---------- skeleton ---------- */
.gm-skel {
  display: block;
  border-radius: 12px;
  background: var(--border);
  opacity: 0.6;
  animation: gm-pulse 1200ms ease-in-out infinite;
}

.gm-skel-eyebrow {
  width: 120px;
  height: 12px;
}

.gm-skel-title {
  width: 200px;
  height: 28px;
}

.gm-skel-card {
  height: 128px;
}

.gm-skel-row {
  height: 84px;
}

/* ---------- animations ---------- */
.gm-enter {
  animation: gm-rise 260ms ease-out both;
}

@keyframes gm-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes gm-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes gm-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 0.75;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
</boltAction>
<boltAction type="file" filePath="src/components/HomeScreen.tsx">import { useMemo, useState } from 'react';
import { Search, UserPlus, Settings } from 'lucide-react';
import MemberRow from './MemberRow';
import {
  remaining as calcRemaining,
  lastVisit,
  isToday,
  daysSince,
} from '../lib/members.js';

type Doc = { id: string; data: any };

type Props = {
  members: Doc[];
  logs: Doc[];
  onOpenMember: (id: string) => void;
  onAdd: () => void;
  onSettings: () => void;
};

type Filter = 'all' | 'low' | 'today' | 'dormant';

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all', label: '전체' },
  { key: 'today', label: '오늘 방문' },
  { key: 'low', label: '잔여 부족' },
  { key: 'dormant', label: '한 달 미방문' },
];

export default function HomeScreen({
  members,
  logs,
  onOpenMember,
  onAdd,
  onSettings,
}: Props) {
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<Filter>('all');

  const rows = useMemo(
    () =>
      members.map((m) => {
        const rem = calcRemaining(m, logs);
        const last = lastVisit(m, logs);
        return { doc: m, remaining: rem, lastVisitAt: last };
      }),
    [members, logs],
  );

  const todayCount = rows.filter((r) => isToday(r.lastVisitAt)).length;
  const lowCount = rows.filter((r) => r.remaining <= 3).length;
  const dormantCount = rows.filter((r) => daysSince(r.lastVisitAt) >= 30).length;

  const visible = rows
    .filter((r) => {
      if (filter === 'today') return isToday(r.lastVisitAt);
      if (filter === 'low') return r.remaining <= 3;
      if (filter === 'dormant') return daysSince(r.lastVisitAt) >= 30;
      return true;
    })
    .filter((r) => {
      const q = query.trim();
      if (!q) return true;
      return (
        r.doc.data.name.includes(q) || (r.doc.data.phone || '').includes(q)
      );
    })
    .sort((a, b) => a.doc.data.name.localeCompare(b.doc.data.name, 'ko'));

  const today = new Date();
  const dateLabel = `${today.getFullYear()}년 ${today.getMonth() + 1}월 ${today.getDate()}일`;

  return (
    <div className="cr-stack-24">
      <header className="gm-header">
        <div className="cr-stack-4">
          <span className="cr-eyebrow">{dateLabel}</span>
          <h1 className="cr-h1">회원 관리</h1>
        </div>
        <button
          type="button"
          className="cr-btn ghost gm-icon-btn"
          onClick={onSettings}
          aria-label="설정 열기"
        >
          <Settings size={20} />
        </button>
      </header>

      <div className="cr-grid-3">
        <StatCard
          label="오늘 방문"
          value={todayCount}
          unit="명"
          sub={`전체 회원 ${members.length}명 중`}
          tone="accent"
        />
        <StatCard
          label="잔여 부족"
          value={lowCount}
          unit="명"
          sub="3회 이하 남은 회원"
          tone="warn"
        />
        <StatCard
          label="한 달 미방문"
          value={dormantCount}
          unit="명"
          sub="연락이 필요해요"
          tone="muted"
        />
      </div>

      <div className="cr-stack-16">
        <div className="gm-searchbar">
          <Search size={16} className="gm-search-icon" />
          <input
            className="cr-input gm-search-input"
            placeholder="이름 또는 연락처 검색"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>

        <div className="gm-chips">
          {FILTERS.map((f) => (
            <button
              key={f.key}
              type="button"
              className={`gm-chip${filter === f.key ? ' active' : ''}`}
              onClick={() => setFilter(f.key)}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      <div className="gm-list">
        {visible.length === 0 ? (
          <div className="cr-card gm-empty cr-stack-16">
            <p className="cr-body">조건에 맞는 회원이 없어요.</p>
            <button type="button" className="cr-btn outline" onClick={onAdd}>
              회원 등록하기
            </button>
          </div>
        ) : (
          visible.map((r, i) => (
            <MemberRow
              key={r.doc.id}
              name={r.doc.data.name}
              plan={r.doc.data.plan}
              remaining={r.remaining}
              lastVisitAt={r.lastVisitAt}
              index={i}
              onOpen={() => onOpenMember(r.doc.id)}
            />
          ))
        )}
      </div>

      <button type="button" className="cr-btn gm-fab" onClick={onAdd}>
        <UserPlus size={16} />
        회원 등록
      </button>
    </div>
  );
}

function StatCard({
  label,
  value,
  unit,
  sub,
  tone,
}: {
  label: string;
  value: number;
  unit: string;
  sub: string;
  tone: 'accent' | 'warn' | 'muted';
}) {
  return (
    <div className="cr-card gm-stat">
      <span className="cr-eyebrow">{label}</span>
      <span className="gm-stat-value" data-tone={tone}>
        {value}
        <span className="gm-stat-unit">{unit}</span>
      </span>
      <span className="cr-caption gm-muted">{sub}</span>
    </div>
  );
}
</boltAction>
<boltAction type="file" filePath="src/components/MemberDetail.tsx">import { useMemo, useState } from 'react';
import { ArrowLeft, Minus, Plus, Phone, CalendarDays, Trash2 } from 'lucide-react';
import type { ReactNode, FormEvent } from 'react';
import {
  remaining as calcRemaining,
  totalCharged,
  lastVisit,
  formatDate,
  formatDateTime,
  relativeLabel,
} from '../lib/members.js';

type Doc = { id: string; data: any };

type Props = {
  member: Doc;
  logs: Doc[];
  onBack: () => void;
  onUse: () => void;
  onCharge: (amount: number) => void;
  onDelete: () => void;
  busy: boolean;
};

const CHARGE_OPTIONS = [10, 20, 30];

export default function MemberDetail({
  member,
  logs,
  onBack,
  onUse,
  onCharge,
  onDelete,
  busy,
}: Props) {
  const [chargeOpen, setChargeOpen] = useState(false);
  const [chargeAmount, setChargeAmount] = useState(10);
  const [confirmDelete, setConfirmDelete] = useState(false);

  const mine = useMemo(
    () =>
      logs
        .filter((l) => l.data.memberId === member.id)
        .sort((a, b) => (a.data.at < b.data.at ? 1 : -1)),
    [logs, member.id],
  );

  const rem = calcRemaining(member, logs);
  const charged = totalCharged(member, logs);
  const used = charged - rem;
  const last = lastVisit(member, logs);
  const progress = charged > 0 ? Math.round((used / charged) * 100) : 0;
  const tone = rem === 0 ? 'err' : rem <= 3 ? 'warn' : 'ok';

  function submitCharge(e: FormEvent) {
    e.preventDefault();
    if (chargeAmount <= 0) return;
    onCharge(chargeAmount);
    setChargeOpen(false);
  }

  return (
    <div className="cr-stack-24">
      <header className="gm-header">
        <button
          type="button"
          className="cr-btn ghost gm-icon-btn"
          onClick={onBack}
          aria-label="목록으로 돌아가기"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="cr-stack-4 gm-header-title">
          <span className="cr-eyebrow">회원 상세</span>
          <h1 className="cr-h1">{member.data.name}</h1>
        </div>
      </header>

      <div className="cr-grid-2">
        <div className="cr-card gm-panel cr-stack-16">
          <div className="cr-row-8 gm-between">
            <span className="cr-eyebrow">남은 횟수</span>
            <span className={`cr-badge ${tone}`}>
              {rem === 0 ? '충전 필요' : rem <= 3 ? '곧 소진' : '이용 가능'}
            </span>
          </div>

          <div className="gm-remain">
            <span className="gm-remain-value" data-tone={tone}>
              {rem}
            </span>
            <span className="cr-body gm-muted">/ {charged}회</span>
          </div>

          <div className="gm-bar" aria-hidden="true">
            <span className="gm-bar-fill" style={{ width: `${progress}%` }} />
          </div>
          <span className="cr-caption gm-muted">
            {used}회 사용 · {progress}% 소진
          </span>

          <div className="cr-row-8">
            <button
              type="button"
              className="cr-btn"
              onClick={onUse}
              disabled={busy || rem <= 0}
            >
              <Minus size={16} />
              1회 차감
            </button>
            <button
              type="button"
              className="cr-btn outline"
              onClick={() => setChargeOpen(true)}
              disabled={busy}
            >
              <Plus size={16} />
              충전
            </button>
          </div>
          {rem <= 0 && (
            <span className="cr-caption gm-warn-text">
              남은 횟수가 없어요. 충전 후 차감할 수 있어요.
            </span>
          )}
        </div>

        <div className="cr-card gm-panel cr-stack-16">
          <span className="cr-eyebrow">회원 정보</span>
          <InfoLine icon={<Phone size={16} />} label="연락처" value={member.data.phone} />
          <InfoLine
            icon={<CalendarDays size={16} />}
            label="등록일"
            value={formatDate(member.data.joinedAt)}
          />
          <InfoLine
            icon={<CalendarDays size={16} />}
            label="최근 방문"
            value={last ? `${formatDate(last)} (${relativeLabel(last)})` : '방문 기록 없음'}
          />
          <div className="gm-divider" />
          <span className="cr-caption gm-muted">이용권</span>
          <span className="cr-body gm-strong">{member.data.plan}</span>
        </div>
      </div>

      <div className="cr-stack-16">
        <span className="cr-eyebrow">이용 기록 {mine.length}건</span>
        {mine.length === 0 ? (
          <div className="cr-card gm-empty">
            <p className="cr-body">아직 기록이 없어요.</p>
          </div>
        ) : (
          <ol className="gm-timeline">
            {mine.map((l, i) => (
              <li
                key={l.id}
                className="gm-timeline-item gm-enter"
                style={{ animationDelay: `${Math.min(i, 10) * 30}ms` }}
              >
                <span
                  className="gm-dot"
                  data-type={l.data.type}
                  aria-hidden="true"
                />
                <span className="gm-timeline-main">
                  <span className="cr-body gm-strong">
                    {l.data.type === 'charge'
                      ? `+${l.data.amount}회 충전`
                      : `-${l.data.amount}회 사용`}
                  </span>
                  <span className="cr-caption gm-muted">
                    {formatDateTime(l.data.at)}
                    {l.data.memo ? ` · ${l.data.memo}` : ''}
                  </span>
                </span>
              </li>
            ))}
          </ol>
        )}
      </div>

      <div className="gm-danger-zone">
        {confirmDelete ? (
          <div className="cr-stack-8">
            <span className="cr-caption gm-warn-text">
              {member.data.name} 회원과 이용 기록이 모두 사라져요. 되돌릴 수 없어요.
            </span>
            <div className="cr-row-8">
              <button
                type="button"
                className="cr-btn danger"
                onClick={onDelete}
                disabled={busy}
              >
                삭제할게요
              </button>
              <button
                type="button"
                className="cr-btn ghost"
                onClick={() => setConfirmDelete(false)}
              >
                취소
              </button>
            </div>
          </div>
        ) : (
          <button
            type="button"
            className="cr-btn outline"
            onClick={() => setConfirmDelete(true)}
          >
            <Trash2 size={16} />
            회원 삭제
          </button>
        )}
      </div>

      {chargeOpen && (
        <div
          className="gm-modal-backdrop"
          onClick={() => setChargeOpen(false)}
          role="presentation"
        >
          <form
            className="cr-overlay gm-modal cr-stack-24"
