import { useCallback, useEffect, useState } from 'react';
import { db, isCloudStorageEnabled, CoralredStorageError } from './lib/coralred-storage.js';
import { loadAll, MEMBERS, LOGS } from './lib/members.js';
import HomeScreen from './components/HomeScreen';
import MemberDetail from './components/MemberDetail';
import AddMember from './components/AddMember';
import SettingsSheet from './components/SettingsSheet';
import Toast from './components/Toast';
import './app.css';

type Doc = { id: string; data: any };
type View = { name: 'home' } | { name: 'detail'; id: string } | { name: 'add' };

export default function App() {
  const [members, setMembers] = useState<Doc[]>([]);
  const [logs, setLogs] = useState<Doc[]>([]);
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading');
  const [view, setView] = useState<View>({ name: 'home' });
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState<{ message: string; tone: 'ok' | 'err' } | null>(null);

  const notify = useCallback((message: string, tone: 'ok' | 'err' = 'ok') => {
    setToast({ message, tone });
  }, []);

  const bootstrap = useCallback(async () => {
    setStatus('loading');
    try {
      const res = await loadAll();
      setMembers(res.members);
      setLogs(res.logs);
      setStatus('ready');
    } catch {
      setStatus('error');
    }
  }, []);

  useEffect(() => {
    bootstrap();
  }, [bootstrap]);

  function handleError(e: unknown) {
    const message =
      e instanceof CoralredStorageError
        ? e.message
        : '문제가 생겼어요. 잠시 후 다시 시도해주세요.';
    notify(message, 'err');
  }

  async function addLog(memberId: string, type: 'use' | 'charge', amount: number, memo = '') {
    setBusy(true);
    try {
      const created = await db.create(LOGS, {
        memberId,
        type,
        amount,
        at: new Date().toISOString(),
        memo,
      });
      setLogs((prev) => [created, ...prev]);
      notify(type === 'use' ? '1회 차감했어요' : `${amount}회 충전했어요`);
    } catch (e) {
      handleError(e);
    } finally {
      setBusy(false);
    }
  }

  async function addMember(v: {
    name: string;
    phone: string;
    plan: string;
    count: number;
  }) {
    setBusy(true);
    try {
      const created = await db.create(MEMBERS, {
        name: v.name,
        phone: v.phone,
        plan: v.plan,
        joinedAt: new Date().toISOString(),
      });
      const firstLog = await db.create(LOGS, {
        memberId: created.id,
        type: 'charge',
        amount: v.count,
        at: new Date().toISOString(),
        memo: '신규 등록',
      });
      setMembers((prev) => [created, ...prev]);
      setLogs((prev) => [firstLog, ...prev]);
      setView({ name: 'detail', id: created.id });
      notify(`${v.name} 회원을 등록했어요`);
    } catch (e) {
      handleError(e);
    } finally {
      setBusy(false);
    }
  }

  async function deleteMember(id: string) {
    setBusy(true);
    try {
      const mine = logs.filter((l) => l.data.memberId === id);
      await Promise.all(mine.map((l) => db.remove(LOGS, l.id)));
      await db.remove(MEMBERS, id);
      setLogs((prev) => prev.filter((l) => l.data.memberId !== id));
      setMembers((prev) => prev.filter((m) => m.id !== id));
      setView({ name: 'home' });
      notify('회원을 삭제했어요');
    } catch (e) {
      handleError(e);
    } finally {
      setBusy(false);
    }
  }

  async function clearSamples() {
    setBusy(true);
    try {
      const sampleMembers = members.filter((m) => m.data.sample);
      const ids = new Set(sampleMembers.map((m) => m.id));
      const sampleLogs = logs.filter((l) => l.data.sample || ids.has(l.data.memberId));

      await Promise.all(sampleLogs.map((l) => db.remove(LOGS, l.id)));
      await Promise.all(sampleMembers.map((m) => db.remove(MEMBERS, m.id)));

      setLogs((prev) => prev.filter((l) => !sampleLogs.some((s) => s.id === l.id)));
      setMembers((prev) => prev.filter((m) => !ids.has(m.id)));
      setSettingsOpen(false);
      setView({ name: 'home' });
      notify('예시 데이터를 지웠어요');
    } catch (e) {
      handleError(e);
    } finally {
      setBusy(false);
    }
  }

  const sampleCount = members.filter((m) => m.data.sample).length;
  const current =
    view.name === 'detail' ? members.find((m) => m.id === view.id) : undefined;

  return (
    <div className="cr-page gm-page">
      {!isCloudStorageEnabled && (
        <div className="gm-notice">
          <span className="cr-badge warn">데이터가 이 기기에만 저장돼요</span>
        </div>
      )}

      {status === 'loading' && <LoadingView />}

      {status === 'error' && (
        <div className="cr-card gm-empty cr-stack-16">
          <p className="cr-body">회원 정보를 불러오지 못했어요.</p>
          <button type="button" className="cr-btn" onClick={bootstrap}>
            다시 시도하기
          </button>
        </div>
      )}

      {status === 'ready' && (
        <div className="gm-view">
          {view.name === 'home' && (
            <HomeScreen
              members={members}
              logs={logs}
              onOpenMember={(id) => setView({ name: 'detail', id })}
              onAdd={() => setView({ name: 'add' })}
              onSettings={() => setSettingsOpen(true)}
            />
          )}

          {view.name === 'detail' &&
            (current ? (
              <MemberDetail
                member={current}
                logs={logs}
                busy={busy}
                onBack={() => setView({ name: 'home' })}
                onUse={() => addLog(current.id, 'use', 1)}
                onCharge={(n) => addLog(current.id, 'charge', n, '추가 결제')}
                onDelete={() => deleteMember(current.id)}
              />
            ) : (
              <div className="cr-card gm-empty cr-stack-16">
                <p className="cr-body">회원을 찾을 수 없어요.</p>
                <button
                  type="button"
                  className="cr-btn"
                  onClick={() => setView({ name: 'home' })}
                >
                  목록으로 가기
                </button>
              </div>
            ))}

          {view.name === 'add' && (
            <AddMember
              busy={busy}
              onBack={() => setView({ name: 'home' })}
              onSubmit={addMember}
            />
          )}
        </div>
      )}

      {settingsOpen && (
        <SettingsSheet
          busy={busy}
          sampleCount={sampleCount}
          onClose={() => setSettingsOpen(false)}
          onClearSamples={clearSamples}
        />
      )}

      {toast && (
        <Toast message={toast.message} tone={toast.tone} onDone={() => setToast(null)} />
      )}
    </div>
  );
}

function LoadingView() {
  return (
    <div className="cr-stack-24">
      <div className="cr-stack-8">
        <span className="gm-skel gm-skel-eyebrow" />
        <span className="gm-skel gm-skel-title" />
      </div>
      <div className="cr-grid-3">
        {[0, 1, 2].map((i) => (
          <span key={i} className="gm-skel gm-skel-card" />
        ))}
      </div>
      <div className="cr-stack-8">
        {[0, 1, 2, 3, 4].map((i) => (
          <span key={i} className="gm-skel gm-skel-row" />
        ))}
      </div>
    </div>
  );
}

