import { db } from './coralred-storage.js';
import { SAMPLE_MEMBERS } from './sampleData.js';

export const MEMBERS = 'members';
export const LOGS = 'usage_logs';

export function remaining(member, logs) {
  const mine = logs.filter((l) => l.data.memberId === member.id);
  return mine.reduce(
    (sum, l) => sum + (l.data.type === 'charge' ? l.data.amount : -l.data.amount),
    0,
  );
}

export function totalCharged(member, logs) {
  return logs
    .filter((l) => l.data.memberId === member.id && l.data.type === 'charge')
    .reduce((sum, l) => sum + l.data.amount, 0);
}

export function lastVisit(member, logs) {
  const uses = logs
    .filter((l) => l.data.memberId === member.id && l.data.type === 'use')
    .map((l) => l.data.at)
    .sort();
  return uses.length ? uses[uses.length - 1] : null;
}

export function isToday(iso) {
  if (!iso) return false;
  const d = new Date(iso);
  const now = new Date();
  return (
    d.getFullYear() === now.getFullYear() &&
    d.getMonth() === now.getMonth() &&
    d.getDate() === now.getDate()
  );
}

export function daysSince(iso) {
  if (!iso) return Infinity;
  const diff = Date.now() - new Date(iso).getTime();
  return Math.floor(diff / 86400000);
}

export function formatDate(iso) {
  if (!iso) return '방문 기록 없음';
  const d = new Date(iso);
  return `${d.getFullYear()}. ${d.getMonth() + 1}. ${d.getDate()}.`;
}

export function formatDateTime(iso) {
  const d = new Date(iso);
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${d.getMonth() + 1}월 ${d.getDate()}일 ${hh}:${mm}`;
}

export function relativeLabel(iso) {
  const n = daysSince(iso);
  if (n === Infinity) return '방문 기록 없음';
  if (n === 0) return '오늘 방문';
  if (n === 1) return '어제 방문';
  if (n < 30) return `${n}일 전 방문`;
  return `${n}일째 미방문`;
}

/** 저장소가 비었으면 예시 데이터를 심고, 심은 결과를 그대로 돌려줌. */
export async function loadAll() {
  const [memberRes, logRes] = await Promise.all([
    db.list(MEMBERS, { limit: 200 }),
    db.list(LOGS, { limit: 500 }),
  ]);

  if (memberRes.items.length > 0) {
    return { members: memberRes.items, logs: logRes.items, seeded: true };
  }

  const members = [];
  const logs = [];

  for (const sample of SAMPLE_MEMBERS) {
    const created = await db.create(MEMBERS, {
      name: sample.name,
      phone: sample.phone,
      plan: sample.plan,
      joinedAt: sample.joinedAt,
      sample: true,
    });
    members.push(created);

    for (const log of sample.logs) {
      const madeLog = await db.create(LOGS, {
        memberId: created.id,
        type: log.type,
        amount: log.amount,
        at: log.at,
        memo: log.memo || '',
        sample: true,
      });
      logs.push(madeLog);
    }
  }

  return { members, logs, seeded: true };
}

