import { useEffect } from 'react';
import { Check, TriangleAlert } from 'lucide-react';

type Props = {
  message: string;
  tone?: 'ok' | 'err';
  onDone: () => void;
};

export default function Toast({ message, tone = 'ok', onDone }: Props) {
  useEffect(() => {
    const t = setTimeout(onDone, 2400);
    return () => clearTimeout(t);
  }, [message, onDone]);

  return (
    <div className="gm-toast" role="status" aria-live="polite">
      <span className="gm-toast-icon" data-tone={tone}>
        {tone === 'ok' ? <Check size={16} /> : <TriangleAlert size={16} />}
      </span>
      <span className="cr-body">{message}</span>
    </div>
  );
}

