import { useMemo, useState } from 'react';
import { Search, UserPlus, Settings } from 'lucide-react';
import MemberRow from './MemberRow';
import {
  remaining as calcRemaining,
  lastVisit,
  isToday,
  daysSince,
} from '../lib/members.js';

type Doc = { id: string; data: any };

type Props = {
  members: Doc[];
  logs: Doc[];
  onOpenMember: (id: string) => void;
  onAdd: () => void;
  onSettings: () => void;
};

type Filter = 'all' | 'low' | 'today' | 'dormant';

const FILTERS: { key: Filter; label: string }[] = [
  { key: 'all', label: '전체' },
  { key: 'today', label: '오늘 방문' },
  { key: 'low', label: '잔여 부족' },
  { key: 'dormant', label: '한 달 미방문' },
];

export default function HomeScreen({
  members,
  logs,
  onOpenMember,
  onAdd,
  onSettings,
}: Props) {
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<Filter>('all');

  const rows = useMemo(
    () =>
      members.map((m) => {
        const rem = calcRemaining(m, logs);
        const last = lastVisit(m, logs);
        return { doc: m, remaining: rem, lastVisitAt: last };
      }),
    [members, logs],
  );

  const todayCount = rows.filter((r) => isToday(r.lastVisitAt)).length;
  const lowCount = rows.filter((r) => r.remaining <= 3).length;
  const dormantCount = rows.filter((r) => daysSince(r.lastVisitAt) >= 30).length;

  const visible = rows
    .filter((r) => {
      if (filter === 'today') return isToday(r.lastVisitAt);
      if (filter === 'low') return r.remaining <= 3;
      if (filter === 'dormant') return daysSince(r.lastVisitAt) >= 30;
      return true;
    })
    .filter((r) => {
      const q = query.trim();
      if (!q) return true;
      return (
        r.doc.data.name.includes(q) || (r.doc.data.phone || '').includes(q)
      );
    })
    .sort((a, b) => a.doc.data.name.localeCompare(b.doc.data.name, 'ko'));

  const today = new Date();
  const dateLabel = `${today.getFullYear()}년 ${today.getMonth() + 1}월 ${today.getDate()}일`;

  return (
    <div className="cr-stack-24">
      <header className="gm-header">
        <div className="cr-stack-4">
          <span className="cr-eyebrow">{dateLabel}</span>
          <h1 className="cr-h1">회원 관리</h1>
        </div>
        <button
          type="button"
          className="cr-btn ghost gm-icon-btn"
          onClick={onSettings}
          aria-label="설정 열기"
        >
          <Settings size={20} />
        </button>
      </header>

      <div className="cr-grid-3">
        <StatCard
          label="오늘 방문"
          value={todayCount}
          unit="명"
          sub={`전체 회원 ${members.length}명 중`}
          tone="accent"
        />
        <StatCard
          label="잔여 부족"
          value={lowCount}
          unit="명"
          sub="3회 이하 남은 회원"
          tone="warn"
        />
        <StatCard
          label="한 달 미방문"
          value={dormantCount}
          unit="명"
          sub="연락이 필요해요"
          tone="muted"
        />
      </div>

      <div className="cr-stack-16">
        <div className="gm-searchbar">
          <Search size={16} className="gm-search-icon" />
          <input
            className="cr-input gm-search-input"
            placeholder="이름 또는 연락처 검색"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>

        <div className="gm-chips">
          {FILTERS.map((f) => (
            <button
              key={f.key}
              type="button"
              className={`gm-chip${filter === f.key ? ' active' : ''}`}
              onClick={() => setFilter(f.key)}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      <div className="gm-list">
        {visible.length === 0 ? (
          <div className="cr-card gm-empty cr-stack-16">
            <p className="cr-body">조건에 맞는 회원이 없어요.</p>
            <button type="button" className="cr-btn outline" onClick={onAdd}>
              회원 등록하기
            </button>
          </div>
        ) : (
          visible.map((r, i) => (
            <MemberRow
              key={r.doc.id}
              name={r.doc.data.name}
              plan={r.doc.data.plan}
              remaining={r.remaining}
              lastVisitAt={r.lastVisitAt}
              index={i}
              onOpen={() => onOpenMember(r.doc.id)}
            />
          ))
        )}
      </div>

      <button type="button" className="cr-btn gm-fab" onClick={onAdd}>
        <UserPlus size={16} />
        회원 등록
      </button>
    </div>
  );
}

function StatCard({
  label,
  value,
  unit,
  sub,
  tone,
}: {
  label: string;
  value: number;
  unit: string;
  sub: string;
  tone: 'accent' | 'warn' | 'muted';
}) {
  return (
    <div className="cr-card gm-stat">
      <span className="cr-eyebrow">{label}</span>
      <span className="gm-stat-value" data-tone={tone}>
        {value}
        <span className="gm-stat-unit">{unit}</span>
      </span>
      <span className="cr-caption gm-muted">{sub}</span>
    </div>
  );
}

