            <Trash2 size={16} />
            회원 삭제
          </button>
        )}
      </div>

      {chargeOpen && (
        <div
          className="gm-modal-backdrop"
          onClick={() => setChargeOpen(false)}
          role="presentation"
        >
          <form
            className="cr-overlay gm-modal cr-stack-24"
            onClick={(e) => e.stopPropagation()}
            onSubmit={submitCharge}
            aria-label="횟수 충전"
          >
            <div className="cr-stack-8">
              <h2 className="cr-h2">횟수 충전</h2>
              <p className="cr-caption gm-muted">
                {member.data.name} 회원에게 추가할 횟수를 골라주세요.
              </p>
            </div>

            <div className="gm-chips">
              {CHARGE_OPTIONS.map((n) => (
                <button
                  key={n}
                  type="button"
                  className={`gm-chip${chargeAmount === n ? ' active' : ''}`}
                  onClick={() => setChargeAmount(n)}
                >
