                {chargeAmount}회 충전하기
              </button>
              <button
                type="button"
                className="cr-btn ghost"
                onClick={() => setChargeOpen(false)}
              >
                취소
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

