import { useState } from 'react';
import type { FormEvent } from 'react';
import { ArrowLeft } from 'lucide-react';

type Props = {
  onBack: () => void;
  onSubmit: (v: { name: string; phone: string; plan: string; count: number }) => void;
  busy: boolean;
};

const PLANS = ['헬스 10회', '헬스 20회', '헬스 30회', 'PT 10회', 'PT 20회', '필라테스 12회'];

function planCount(plan: string) {
  const m = plan.match(/(\d+)회/);
  return m ? Number(m[1]) : 10;
}

export default function AddMember({ onBack, onSubmit, busy }: Props) {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [plan, setPlan] = useState(PLANS[0]);
  const [count, setCount] = useState(planCount(PLANS[0]));
  const [error, setError] = useState('');

  function pickPlan(p: string) {
    setPlan(p);
    setCount(planCount(p));
  }

  function submit(e: FormEvent) {
    e.preventDefault();
    if (!name.trim()) {
      setError('이름을 입력해주세요.');
      return;
    }
    if (count <= 0) {
      setError('시작 횟수는 1회 이상이어야 해요.');
      return;
    }
    setError('');
    onSubmit({ name: name.trim(), phone: phone.trim(), plan, count });
  }

  return (
    <div className="cr-stack-24">
      <header className="gm-header">
        <button
          type="button"
          className="cr-btn ghost gm-icon-btn"
          onClick={onBack}
          aria-label="목록으로 돌아가기"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="cr-stack-4 gm-header-title">
          <span className="cr-eyebrow">새 회원</span>
          <h1 className="cr-h1">회원 등록</h1>
        </div>
      </header>

      <form className="cr-card cr-stack-24 gm-form" onSubmit={submit}>
        <div className="cr-stack-8">
          <label className="cr-label" htmlFor="f-name">
            이름
          </label>
          <input
            id="f-name"
            className="cr-input"
            placeholder="김서연"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
        </div>

        <div className="cr-stack-8">
          <label className="cr-label" htmlFor="f-phone">
            연락처
          </label>
          <input
            id="f-phone"
            className="cr-input"
            placeholder="010-0000-0000"
            inputMode="tel"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </div>

        <div className="cr-stack-8">
          <span className="cr-label">이용권</span>
          <div className="gm-chips">
            {PLANS.map((p) => (
              <button
                key={p}
                type="button"
                className={`gm-chip${plan === p ? ' active' : ''}`}
                onClick={() => pickPlan(p)}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        <div className="cr-stack-8">
          <label className="cr-label" htmlFor="f-count">
            시작 횟수
          </label>
          <input
            id="f-count"
            className="cr-input"
            type="number"
            min={1}
            value={count}
            onChange={(e) => setCount(Number(e.target.value) || 0)}
          />
          <span className="cr-caption gm-muted">
            이용권을 고르면 자동으로 채워져요. 필요하면 직접 고칠 수 있어요.
          </span>
        </div>

        {error && <span className="cr-caption gm-err-text">{error}</span>}

        <div className="cr-row-8">
          <button type="submit" className="cr-btn lg" disabled={busy}>
            {busy ? '등록 중...' : '회원 등록하기'}
          </button>
          <button type="button" className="cr-btn ghost" onClick={onBack}>
            취소
          </button>
        </div>
      </form>
    </div>
  );
}

