  onClose: () => void;
  onClearSamples: () => void;
  sampleCount: number;
  busy: boolean;
};

export default function SettingsSheet({
  onClose,
  onClearSamples,
  sampleCount,
  busy,
}: Props) {
  return (
    <div className="gm-modal-backdrop" onClick={onClose} role="presentation">
      <div
        className="cr-overlay gm-modal"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-label="설정"
      >
        <div className="cr-stack-24">
          <div className="cr-row-8 gm-between">
            <h2 className="cr-h2">설정</h2>
            <button
              type="button"
              className="cr-btn ghost gm-icon-btn"
              onClick={onClose}
              aria-label="설정 닫기"
            >
              <X size={20} />
            </button>
          </div>

          <div className="cr-stack-8">
            <span className="cr-label">예시 데이터</span>
            <p className="cr-caption gm-muted">
              지금 보이는 회원 {sampleCount}명은 예시 데이터예요. 한 번에 지우고 실제 회원만
              관리할 수 있어요.
            </p>
            <button
              type="button"
              className="cr-btn outline"
              onClick={onClearSamples}
              disabled={busy || sampleCount === 0}
            >
              {busy ? '지우는 중...' : '예시 데이터 지우기'}
            </button>
          </div>

          <div className="gm-divider" />

          <div className="cr-stack-4">
            <span className="cr-label">저장 위치</span>
            <p className="cr-caption gm-muted">
              회원 정보는 이 기기에 연결된 저장소에 보관돼요. 다른 기기와는 따로 관리돼요.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

